// This code has been fully generated by an AI.

package web

import (
	"context"
	"fmt"
	"math"
	"time"

	"github.com/stefanluchs/my-velo/internal/routesvg"
	"github.com/stefanluchs/my-velo/internal/sport"
	"github.com/stefanluchs/my-velo/internal/store"
)

// tileStat is one figure on an activity tile, e.g. "Distanz 24,3 km".
type tileStat struct {
	Label, Value, Unit string
}

// activityTile is an activity prepared for the Strava-like tile list.
type activityTile struct {
	store.Activity
	Title    string
	Category sport.Category
	Date     string
	Stats    []tileStat
	// Route is nil for activities without GPS track.
	Route *routesvg.Route
}

// feedItem is one tile, optionally preceded by a month heading.
type feedItem struct {
	Month *monthHead
	Tile  activityTile
}

type monthHead struct {
	Label  string
	Totals store.Totals
}

var weekdayNames = [...]string{"So", "Mo", "Di", "Mi", "Do", "Fr", "Sa"}

var monthNamesLong = [...]string{"Januar", "Februar", "März", "April", "Mai", "Juni", "Juli", "August",
	"September", "Oktober", "November", "Dezember"}

// tileDate formats the local start like "Mo, 20.10.2026 · 15:29".
func tileDate(a store.Activity) string {
	t := a.LocalStart()
	return fmt.Sprintf("%s, %s · %s", weekdayNames[t.Weekday()], t.Format("02.01.2006"), t.Format("15:04"))
}

// shortDuration formats seconds as "45 min" or "1:07 h" (value and unit).
func shortDuration(seconds float64) (string, string) {
	m := int(math.Round(seconds / 60))
	if m < 60 {
		return fmt.Sprint(m), "min"
	}
	return fmt.Sprintf("%d:%02d", m/60, m%60), "h"
}

// pace formats a speed in m/s as min/km, e.g. "5:12".
func pace(mps float64) string {
	if mps <= 0 {
		return "–"
	}
	s := int(math.Round(1000 / mps))
	return fmt.Sprintf("%d:%02d", s/60, s%60)
}

// tileStats picks the three figures that matter for the kind of activity,
// as Strava does: distance, elevation and time for rides, pace for runs,
// heart rate and power for activities without distance.
func tileStats(a store.Activity, cat sport.Category) []tileStat {
	dv, du := shortDuration(a.TimerS)
	timeStat := tileStat{"Zeit", dv, du}
	if a.DistanceM < 100 {
		out := []tileStat{timeStat}
		if a.AvgHR > 0 {
			out = append(out, tileStat{"⌀ HF", fmt.Sprint(a.AvgHR), "bpm"})
		}
		if a.AvgPower > 0 {
			out = append(out, tileStat{"⌀ Leistung", fmt.Sprint(a.AvgPower), "W"})
		}
		return out
	}
	dist := tileStat{"Distanz", km(a.DistanceM), "km"}
	switch {
	case cat.ID == "run":
		return []tileStat{dist, {"Pace", pace(a.AvgSpeed), "/km"}, timeStat}
	case cat.ID == "indoor" && a.AvgPower > 0:
		return []tileStat{dist, {"⌀ Leistung", fmt.Sprint(a.AvgPower), "W"}, timeStat}
	case a.AscentM > 0:
		return []tileStat{dist, {"Höhenmeter", fmt.Sprint(a.AscentM), "m"}, timeStat}
	default:
		return []tileStat{dist, {"⌀ Tempo", kmh(a.AvgSpeed), "km/h"}, timeStat}
	}
}

// tiles prepares activities for the tile list including their mini routes.
func (s *server) tiles(ctx context.Context, list []store.Activity) ([]activityTile, error) {
	ids := make([]int64, 0, len(list))
	for _, a := range list {
		if a.BBox != nil {
			ids = append(ids, a.ID)
		}
	}
	polylines, err := s.Store.Polylines(ctx, ids)
	if err != nil {
		return nil, err
	}
	out := make([]activityTile, len(list))
	for i, a := range list {
		cat := sport.CategoryOf(a.Sport, a.SubSport)
		t := activityTile{Activity: a, Title: a.Name, Category: cat, Date: tileDate(a), Stats: tileStats(a, cat)}
		if t.Title == "" {
			t.Title = sport.Label(a.Sport, a.SubSport)
		}
		if p, ok := polylines[a.ID]; ok {
			if r, ok := routesvg.FromPolyline(p); ok {
				t.Route = &r
			}
		}
		out[i] = t
	}
	return out, nil
}

// monthKey returns "2026-10" for the local start of a.
func monthKey(a store.Activity) string { return a.LocalStart().Format("2006-01") }

// monthLabel turns "2026-10" into "Oktober 2026".
func monthLabel(key string) string {
	t, err := time.Parse("2006-01", key)
	if err != nil {
		return key
	}
	return fmt.Sprintf("%s %d", monthNamesLong[t.Month()-1], t.Year())
}

// feed groups tiles by month. prevMonth is the month of the activity shown
// just before the first tile (empty on a fresh page), so pages appended by
// infinite scrolling do not repeat a heading.
func feed(tiles []activityTile, prevMonth string, months map[string]store.Totals) []feedItem {
	out := make([]feedItem, len(tiles))
	for i, t := range tiles {
		out[i].Tile = t
		if k := monthKey(t.Activity); k != prevMonth {
			out[i].Month = &monthHead{Label: monthLabel(k), Totals: months[k]}
			prevMonth = k
		}
	}
	return out
}

// pluralize returns singular for n == 1, otherwise plural.
func pluralize(n int, singular, plural string) string {
	if n == 1 {
		return singular
	}
	return plural
}
